cypress_script:
describe('API Endpoint Documentation List', () => {
  it('should display the API documentation correctly', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.title().should('eq', 'Automation Practice for API Testing');
    cy.contains('APIs List for practice').should('be.visible');
    cy.get('#collapse1').contains('API URL: https://automationexercise.com/api/productsList').should('be.visible');
    cy.get('#susbscribe_email').should('have.attr', 'placeholder', 'Your email address');
    cy.get('#subscribe').should('have.class', 'btn btn-default');
  });
  it('should not change URL on empty subscription submit', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('#subscribe').click();
    cy.url().should('eq', 'https://automationexercise.com/api_list');
    cy.get('#susbscribe_email').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('API Endpoint Documentation List', () => {
  test('should display the API documentation correctly', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await expect(page).toHaveTitle('Automation Practice for API Testing');
    await expect(page.locator('text=APIs List for practice')).toBeVisible();
    await expect(page.locator('#collapse1').locator('text=API URL: https://automationexercise.com/api/productsList')).toBeVisible();
    await expect(page.locator('#susbscribe_email')).toHaveAttribute('placeholder', 'Your email address');
    await expect(page.locator('#subscribe')).toHaveClass(/btn btn-default/);
  });
  test('should not change URL on empty subscription submit', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await page.click('#subscribe');
    await expect(page).toHaveURL('https://automationexercise.com/api_list');
    await expect(page.locator('#susbscribe_email')).toBeVisible();
  });
});
